CREATE INDEX idx_automation_runs_seed_created ON automation_runs(seed_id,created_at DESC,id DESC) WHERE seed_id<>'';
CREATE INDEX idx_automation_runs_session_created ON automation_runs(session_id, created_at DESC, id DESC);
CREATE INDEX idx_automation_runs_ticket_created ON automation_runs(ticket_id, created_at DESC, id DESC);
