CREATE TABLE bus_events ( seq INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, subject TEXT NOT NULL DEFAULT '', payload TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL );
CREATE TABLE chief_of_staff_dispatches ( id TEXT PRIMARY KEY, chief_session_id TEXT NOT NULL, session_id TEXT NOT NULL UNIQUE, brief TEXT NOT NULL, label TEXT NOT NULL, agent TEXT NOT NULL, directory TEXT NOT NULL, branch TEXT NOT NULL DEFAULT '', latest_report TEXT NOT NULL DEFAULT '', reported_at TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL , structured_report_json TEXT NOT NULL DEFAULT '', closed_state TEXT NOT NULL DEFAULT '', profile_id TEXT NOT NULL DEFAULT '');
