CREATE TABLE delegation_operations ( request_id TEXT PRIMARY KEY, operation_id TEXT NOT NULL UNIQUE, request_json TEXT NOT NULL, state TEXT NOT NULL, progress TEXT NOT NULL, session_id TEXT NOT NULL, ticket_id TEXT NOT NULL DEFAULT '', worktree_path TEXT NOT NULL DEFAULT '', worktree_owned INTEGER NOT NULL DEFAULT 0, result_json TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL , worktree_token TEXT NOT NULL DEFAULT '', chief_session_id TEXT NOT NULL DEFAULT '', resolved_preferences TEXT NOT NULL DEFAULT '', directory TEXT NOT NULL DEFAULT '', branch TEXT NOT NULL DEFAULT '', base_commit TEXT NOT NULL DEFAULT '', handoff_note_id TEXT NOT NULL DEFAULT '', failure_code TEXT NOT NULL DEFAULT '', handover_seed_rev INTEGER NOT NULL DEFAULT 0, handover_tender_session TEXT NOT NULL DEFAULT '', handover_tender_member TEXT NOT NULL DEFAULT '', parent_seed_id TEXT NOT NULL DEFAULT '', profile_id TEXT NOT NULL DEFAULT '', handover_tender TEXT NOT NULL DEFAULT '');
