CREATE TABLE markdown_annotation_drafts ( path TEXT PRIMARY KEY, annotations_json TEXT NOT NULL, generation INTEGER NOT NULL, tombstone_generation INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL );
CREATE TABLE monitored_worktree_repositories ( main_repo TEXT PRIMARY KEY NOT NULL );
CREATE TABLE notifications ( id TEXT PRIMARY KEY, kind TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', detail TEXT NOT NULL DEFAULT '', source_kind TEXT NOT NULL DEFAULT '', source_id TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, read_at TEXT NOT NULL DEFAULT '' , severity TEXT NOT NULL DEFAULT 'info', trigger TEXT NOT NULL DEFAULT '', impact TEXT NOT NULL DEFAULT '', cause TEXT NOT NULL DEFAULT '', diagnostic TEXT NOT NULL DEFAULT '', actions_json TEXT NOT NULL DEFAULT '');
CREATE TABLE "outpost_outbox" ( id INTEGER PRIMARY KEY AUTOINCREMENT, host TEXT NOT NULL, tbl TEXT NOT NULL, key TEXT NOT NULL, UNIQUE (host, tbl, key) );
CREATE TABLE outposts ( id TEXT PRIMARY KEY, name TEXT NOT NULL, destination TEXT NOT NULL UNIQUE, host_key TEXT, daemon_id TEXT UNIQUE, added_at TEXT NOT NULL, paired_at TEXT );
CREATE TABLE peer_messages ( id TEXT PRIMARY KEY, sender TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL );
CREATE TABLE pr_interactions ( pr_id TEXT PRIMARY KEY, last_visited_at TEXT, last_approved_at TEXT, last_seen_sha TEXT, last_seen_comment_count INTEGER , last_seen_ci_status TEXT);
CREATE TABLE profile_migration ( id INTEGER PRIMARY KEY CHECK (id = 1), schema_version INTEGER NOT NULL, phase TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, imported_groups TEXT NOT NULL DEFAULT '', draft TEXT NOT NULL DEFAULT '' , launch_review_complete INTEGER NOT NULL DEFAULT 0);
CREATE TABLE profile_settings ( profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, key TEXT NOT NULL, value TEXT NOT NULL, PRIMARY KEY (profile_id, key) );
CREATE TABLE profiles ( id TEXT PRIMARY KEY, name TEXT NOT NULL, current_desktop_id TEXT NOT NULL DEFAULT '', last_used_at TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, deleted_at TEXT NOT NULL DEFAULT '' , chief_session_id TEXT NOT NULL DEFAULT '', chief_member TEXT NOT NULL DEFAULT '');
CREATE TABLE prs ( id TEXT PRIMARY KEY, repo TEXT NOT NULL, number INTEGER NOT NULL, title TEXT NOT NULL, url TEXT NOT NULL, role TEXT NOT NULL, state TEXT NOT NULL, reason TEXT, muted INTEGER NOT NULL DEFAULT 0, details_fetched INTEGER NOT NULL DEFAULT 0, details_fetched_at TEXT, mergeable INTEGER, mergeable_state TEXT, ci_status TEXT, review_status TEXT , head_sha TEXT, head_branch TEXT, comment_count INTEGER NOT NULL DEFAULT 0, approved_by_me INTEGER NOT NULL DEFAULT 0, heat_state TEXT NOT NULL DEFAULT 'cold', last_heat_activity_at TEXT, author TEXT NOT NULL DEFAULT '', host TEXT NOT NULL DEFAULT 'github.com');
CREATE TABLE pull_request_watches ( address TEXT NOT NULL, session_id TEXT NOT NULL, pr_id TEXT NOT NULL, mode TEXT NOT NULL, reviewer TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, cursor_json TEXT NOT NULL DEFAULT '{}', last_error TEXT NOT NULL DEFAULT '',feedback_error TEXT NOT NULL DEFAULT '', outage_active INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(address,pr_id));
CREATE TABLE quick_capture_attachments ( profile_id TEXT NOT NULL, capture_id TEXT NOT NULL, attachment_id TEXT NOT NULL, name TEXT NOT NULL, media_type TEXT NOT NULL DEFAULT '', byte_count INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(profile_id, capture_id, attachment_id) );
CREATE TABLE quick_captures ( profile_id TEXT NOT NULL, id TEXT NOT NULL, inbox_item_id TEXT NOT NULL UNIQUE, submission TEXT NOT NULL, mailbox_kind TEXT NOT NULL, mailbox_member_id TEXT NOT NULL DEFAULT '', body TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(profile_id,id) );
CREATE TABLE recent_locations ( path TEXT PRIMARY KEY, last_seen TEXT NOT NULL, use_count INTEGER NOT NULL DEFAULT 1 );
CREATE TABLE repo_integration_branches ( main_repo TEXT PRIMARY KEY, branch TEXT NOT NULL, source TEXT NOT NULL, resolved_at TEXT NOT NULL );
CREATE TABLE repo_merged_branches ( main_repo TEXT NOT NULL, branch TEXT NOT NULL, merged_at TEXT NOT NULL DEFAULT '', number INTEGER NOT NULL DEFAULT 0, url TEXT NOT NULL DEFAULT '', head_sha TEXT NOT NULL DEFAULT '', observed_at TEXT NOT NULL, PRIMARY KEY (main_repo, branch) );
CREATE TABLE repos ( repo TEXT PRIMARY KEY, muted INTEGER NOT NULL DEFAULT 0, collapsed INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE review_comments ( id TEXT PRIMARY KEY, review_id TEXT NOT NULL, filepath TEXT NOT NULL, line_start INTEGER NOT NULL, line_end INTEGER NOT NULL, content TEXT NOT NULL, author TEXT NOT NULL, resolved INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, resolved_by TEXT NOT NULL DEFAULT '', resolved_at TEXT NOT NULL DEFAULT '', FOREIGN KEY (review_id) REFERENCES reviews(id) ON DELETE CASCADE );
CREATE TABLE review_viewed_files ( review_id TEXT NOT NULL, filepath TEXT NOT NULL, viewed_at TEXT NOT NULL, PRIMARY KEY (review_id, filepath), FOREIGN KEY (review_id) REFERENCES reviews(id) ON DELETE CASCADE );
CREATE TABLE reviewer_sessions ( id TEXT PRIMARY KEY, review_id TEXT NOT NULL, commit_sha TEXT NOT NULL, transcript TEXT NOT NULL, started_at TEXT NOT NULL, completed_at TEXT, FOREIGN KEY (review_id) REFERENCES reviews(id) ON DELETE CASCADE );
CREATE TABLE reviews ( id TEXT PRIMARY KEY, branch TEXT NOT NULL, pr_number INTEGER, repo_path TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(repo_path, branch) );
CREATE TABLE schema_migrations ( version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL );
CREATE TABLE session_annotation_drafts ( session_id TEXT PRIMARY KEY, annotations_json TEXT NOT NULL, generation INTEGER NOT NULL, tombstone_generation INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL , note TEXT NOT NULL DEFAULT '');
CREATE TABLE session_exit_screens ( session_id TEXT PRIMARY KEY, text TEXT NOT NULL DEFAULT '', cols INTEGER NOT NULL DEFAULT 0, rows INTEGER NOT NULL DEFAULT 0, exit_code INTEGER NOT NULL DEFAULT 0, exit_signal TEXT NOT NULL DEFAULT '', exited_at TEXT NOT NULL );
CREATE TABLE session_pull_requests ( session_id TEXT NOT NULL, pr_id TEXT NOT NULL, repository TEXT NOT NULL, number INTEGER NOT NULL, url TEXT NOT NULL, created_at TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', draft INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'open', ci_status TEXT NOT NULL DEFAULT '', review_status TEXT NOT NULL DEFAULT '', mergeable_state TEXT NOT NULL DEFAULT '', head_sha TEXT NOT NULL DEFAULT '', head_branch TEXT NOT NULL DEFAULT '', status_fetched_at TEXT NOT NULL DEFAULT '', last_activity_at TEXT NOT NULL DEFAULT '', status_checked_at TEXT NOT NULL DEFAULT '', readiness_state TEXT NOT NULL DEFAULT '', readiness_reason TEXT NOT NULL DEFAULT '', settling_until TEXT NOT NULL DEFAULT '', watch_health TEXT NOT NULL DEFAULT '', watch_error TEXT NOT NULL DEFAULT '', watch_last_checked_at TEXT NOT NULL DEFAULT '', PRIMARY KEY (session_id, pr_id) );
CREATE TABLE session_runtime ( session_id TEXT PRIMARY KEY, state TEXT NOT NULL DEFAULT 'launching', state_since TEXT NOT NULL DEFAULT '', state_updated_at TEXT NOT NULL DEFAULT '', last_seen TEXT NOT NULL DEFAULT '', branch TEXT, is_worktree INTEGER NOT NULL DEFAULT 0, main_repo TEXT, repository TEXT NOT NULL DEFAULT '', agent_metadata TEXT NOT NULL DEFAULT '', agent_driver_plugin_name TEXT NOT NULL DEFAULT '', agent_driver_run_id TEXT NOT NULL DEFAULT '', agent_driver_report_seq INTEGER NOT NULL DEFAULT 0, agent_driver_transcript_path TEXT NOT NULL DEFAULT '', turn_settled_at TEXT NOT NULL DEFAULT '', turn_opened_at TEXT NOT NULL DEFAULT '', turn_snoozed_until TEXT NOT NULL DEFAULT '', turn_agent_at TEXT NOT NULL DEFAULT '', turn_requested_at TEXT NOT NULL DEFAULT '', last_model_request_at TEXT, harness_title TEXT NOT NULL DEFAULT '', session_cost_json TEXT NOT NULL DEFAULT '', pending_conversations TEXT NOT NULL DEFAULT '', pull_requests TEXT NOT NULL DEFAULT '' , home_daemon_id TEXT NOT NULL DEFAULT '', live INTEGER NOT NULL DEFAULT 0, agent TEXT NOT NULL DEFAULT '', conversation_native_id TEXT NOT NULL DEFAULT '', conversation_transcript_path TEXT NOT NULL DEFAULT '');
CREATE TABLE session_teardown_tombstones ( session_id TEXT PRIMARY KEY, requested_at TEXT NOT NULL, driver_plugin_name TEXT NOT NULL DEFAULT '', driver_run_id TEXT NOT NULL DEFAULT '', driver_report_seq INTEGER NOT NULL DEFAULT 0 , driver_terminal_id TEXT NOT NULL DEFAULT '');
CREATE TABLE sessions ( id TEXT PRIMARY KEY, user_label TEXT NOT NULL, directory TEXT NOT NULL, agent TEXT NOT NULL DEFAULT 'codex', resume_session_id TEXT NOT NULL DEFAULT '', closed_intentionally_at TEXT NOT NULL DEFAULT '', launch_intent TEXT NOT NULL DEFAULT '', parent_session_id TEXT NOT NULL DEFAULT '', context_window_cap INTEGER NOT NULL DEFAULT 0, activity TEXT NOT NULL DEFAULT '', activity_at TEXT NOT NULL DEFAULT '', activity_cursor TEXT NOT NULL DEFAULT '', transcript_path TEXT NOT NULL DEFAULT '', closed_at TEXT NOT NULL DEFAULT '', closed_by TEXT NOT NULL DEFAULT '', close_reason TEXT NOT NULL DEFAULT '', launched_at TEXT NOT NULL DEFAULT '', profile_id TEXT NOT NULL DEFAULT '', last_desktop_id TEXT NOT NULL DEFAULT '', succeeds TEXT NOT NULL DEFAULT '', priority INTEGER NOT NULL DEFAULT 0, link TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT '', host TEXT NOT NULL DEFAULT '', copied_from TEXT NOT NULL DEFAULT '', command_terminal INTEGER NOT NULL DEFAULT 0, member_key TEXT NOT NULL DEFAULT '');
CREATE TABLE "settings" ( key TEXT NOT NULL, value TEXT, copied_from TEXT NOT NULL DEFAULT '', PRIMARY KEY (key, copied_from) );
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE supervised_parks ( child TEXT PRIMARY KEY, parked_at TEXT NOT NULL, restart_attempt INTEGER NOT NULL DEFAULT 0, exit_at TEXT NOT NULL DEFAULT '', exit_code INTEGER, exit_signal TEXT NOT NULL DEFAULT '', exit_error TEXT NOT NULL DEFAULT '' );
CREATE TABLE tasks ( id TEXT PRIMARY KEY, kind TEXT NOT NULL, subject TEXT NOT NULL, state TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, last_error TEXT NOT NULL DEFAULT '', meta_json TEXT NOT NULL DEFAULT '', requeued INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE terminal_bindings ( terminal_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE );
CREATE TABLE terminal_views ( terminal_id TEXT PRIMARY KEY, link TEXT NOT NULL, profile_id TEXT NOT NULL, created_at TEXT NOT NULL );
CREATE TABLE vents ( id TEXT PRIMARY KEY, profile_id TEXT NOT NULL, session_id TEXT NOT NULL, turn TEXT NOT NULL, text TEXT NOT NULL, context TEXT NOT NULL, created_at TEXT NOT NULL, withdrawn_at TEXT, dismissed_at TEXT , planted_seed_id TEXT, outbox_seq INTEGER, sent_at TEXT, kind TEXT NOT NULL DEFAULT 'attn');
CREATE TABLE worktree_sweep_log ( id TEXT PRIMARY KEY, path TEXT NOT NULL, main_repo TEXT NOT NULL, branch TEXT NOT NULL DEFAULT '', action TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', at TEXT NOT NULL );
CREATE TABLE worktrees ( path TEXT PRIMARY KEY, branch TEXT NOT NULL, main_repo TEXT NOT NULL, created_at TEXT NOT NULL , origin TEXT NOT NULL DEFAULT '', pinned_at TEXT NOT NULL DEFAULT '', observed_at TEXT NOT NULL DEFAULT '', head_sha TEXT NOT NULL DEFAULT '', detached INTEGER NOT NULL DEFAULT 0, dirty INTEGER NOT NULL DEFAULT 0, dirty_files INTEGER NOT NULL DEFAULT 0, stashes INTEGER NOT NULL DEFAULT 0, unpushed INTEGER NOT NULL DEFAULT 0, merged_signal TEXT NOT NULL DEFAULT '', prunable INTEGER NOT NULL DEFAULT 0, last_activity_at TEXT NOT NULL DEFAULT '', sweep_status TEXT NOT NULL DEFAULT '', sweep_reason TEXT NOT NULL DEFAULT '', sweep_at TEXT NOT NULL DEFAULT '', refresh_error TEXT NOT NULL DEFAULT '');
CREATE TRIGGER launch_automation_deleted AFTER UPDATE OF deleted_at ON automation_definitions WHEN NEW.deleted_at != '' BEGIN DELETE FROM launch_desktops WHERE kind = 'automation' AND item_id = NEW.id; END;
CREATE TRIGGER launch_review_crew_insert AFTER INSERT ON crew_members BEGIN UPDATE profile_migration SET revision = revision + 1 WHERE phase = 'launch_required'; END;
CREATE TRIGGER launch_review_crew_update AFTER UPDATE ON crew_members WHEN OLD.profile_id != NEW.profile_id OR OLD.name != NEW.name BEGIN UPDATE profile_migration SET revision = revision + 1 WHERE phase = 'launch_required'; END;
CREATE TRIGGER launch_review_definition_insert AFTER INSERT ON automation_definitions BEGIN UPDATE profile_migration SET revision = revision + 1 WHERE phase = 'launch_required'; END;
CREATE TRIGGER launch_review_definition_update AFTER UPDATE OF name, profile_id, deleted_at ON automation_definitions WHEN OLD.name != NEW.name OR OLD.profile_id != NEW.profile_id OR OLD.deleted_at != NEW.deleted_at BEGIN UPDATE profile_migration SET revision = revision + 1 WHERE phase = 'launch_required'; END;
CREATE TRIGGER launch_review_setting_delete AFTER DELETE ON launch_desktops BEGIN UPDATE profile_migration SET revision = revision + 1 WHERE phase = 'launch_required'; END;
CREATE TRIGGER launch_review_setting_insert AFTER INSERT ON launch_desktops BEGIN UPDATE profile_migration SET revision = revision + 1 WHERE phase = 'launch_required'; END;
CREATE TRIGGER launch_review_setting_update AFTER UPDATE ON launch_desktops BEGIN UPDATE profile_migration SET revision = revision + 1 WHERE phase = 'launch_required'; END;
CREATE TRIGGER outpost_copy_binding_delete AFTER DELETE ON terminal_bindings WHEN EXISTS (SELECT 1 FROM sessions s JOIN outposts o ON o.id = s.host WHERE s.id = OLD.session_id) BEGIN DELETE FROM outpost_outbox WHERE tbl = 'terminal_bindings' AND key = OLD.terminal_id; INSERT INTO outpost_outbox (host, tbl, key) SELECT host, 'terminal_bindings', OLD.terminal_id FROM sessions WHERE id = OLD.session_id; END;
CREATE TRIGGER outpost_copy_binding_insert AFTER INSERT ON terminal_bindings WHEN EXISTS (SELECT 1 FROM sessions s JOIN outposts o ON o.id = s.host WHERE s.id = NEW.session_id) BEGIN DELETE FROM outpost_outbox WHERE tbl = 'terminal_bindings' AND key = NEW.terminal_id; INSERT INTO outpost_outbox (host, tbl, key) SELECT host, 'terminal_bindings', NEW.terminal_id FROM sessions WHERE id = NEW.session_id; END;
CREATE TRIGGER outpost_copy_binding_update AFTER UPDATE ON terminal_bindings WHEN EXISTS (SELECT 1 FROM sessions s JOIN outposts o ON o.id = s.host WHERE s.id IN (OLD.session_id, NEW.session_id)) BEGIN DELETE FROM outpost_outbox WHERE tbl = 'terminal_bindings' AND key = NEW.terminal_id; INSERT INTO outpost_outbox (host, tbl, key) SELECT s.host, 'terminal_bindings', NEW.terminal_id FROM sessions s JOIN outposts o ON o.id = s.host WHERE s.id IN (OLD.session_id, NEW.session_id) LIMIT 1; END;
CREATE TRIGGER outpost_copy_session_delete AFTER DELETE ON sessions WHEN OLD.host != '' AND EXISTS (SELECT 1 FROM outposts WHERE id = OLD.host) BEGIN DELETE FROM outpost_outbox WHERE tbl = 'sessions' AND key = OLD.id; INSERT INTO outpost_outbox (host, tbl, key) VALUES (OLD.host, 'sessions', OLD.id); END;
CREATE TRIGGER outpost_copy_session_insert AFTER INSERT ON sessions WHEN NEW.host != '' AND EXISTS (SELECT 1 FROM outposts WHERE id = NEW.host) BEGIN DELETE FROM outpost_outbox WHERE tbl = 'sessions' AND key = NEW.id; INSERT INTO outpost_outbox (host, tbl, key) VALUES (NEW.host, 'sessions', NEW.id); END;
CREATE TRIGGER outpost_copy_session_update AFTER UPDATE ON sessions WHEN NEW.host != '' AND EXISTS (SELECT 1 FROM outposts WHERE id = NEW.host) BEGIN DELETE FROM outpost_outbox WHERE tbl = 'sessions' AND key = NEW.id; INSERT INTO outpost_outbox (host, tbl, key) VALUES (NEW.host, 'sessions', NEW.id); END;
CREATE TRIGGER outpost_copy_setting_delete AFTER DELETE ON settings WHEN OLD.copied_from = '' AND attn_home_setting(OLD.key) BEGIN DELETE FROM outpost_outbox WHERE tbl = 'settings' AND key = OLD.key; INSERT INTO outpost_outbox(host, tbl, key) SELECT id, 'settings', OLD.key FROM outposts; END;
CREATE TRIGGER outpost_copy_setting_insert AFTER INSERT ON settings WHEN NEW.copied_from = '' AND attn_home_setting(NEW.key) BEGIN DELETE FROM outpost_outbox WHERE tbl = 'settings' AND key = NEW.key; INSERT INTO outpost_outbox(host, tbl, key) SELECT id, 'settings', NEW.key FROM outposts; END;
CREATE TRIGGER outpost_copy_setting_update AFTER UPDATE ON settings WHEN NEW.copied_from = '' AND attn_home_setting(NEW.key) BEGIN DELETE FROM outpost_outbox WHERE tbl = 'settings' AND key = NEW.key; INSERT INTO outpost_outbox(host, tbl, key) SELECT id, 'settings', NEW.key FROM outposts; END;
CREATE TRIGGER refuse_copied_sessions_delete BEFORE DELETE ON sessions WHEN (OLD.copied_from != '') BEGIN SELECT attn_require_copy_applier('sessions', OLD.id); END;
CREATE TRIGGER refuse_copied_sessions_insert BEFORE INSERT ON sessions WHEN (NEW.copied_from != '' OR EXISTS (SELECT 1 FROM sessions WHERE id = NEW.id AND copied_from != '')) BEGIN SELECT attn_require_copy_applier('sessions', NEW.id); END;
CREATE TRIGGER refuse_copied_sessions_update BEFORE UPDATE ON sessions WHEN (OLD.copied_from != '' OR NEW.copied_from != '') BEGIN SELECT attn_require_copy_applier('sessions', OLD.id); END;
CREATE TRIGGER refuse_copied_settings_delete BEFORE DELETE ON settings WHEN (OLD.copied_from != '') BEGIN SELECT attn_require_copy_applier('settings', OLD.key); END;
CREATE TRIGGER refuse_copied_settings_insert BEFORE INSERT ON settings WHEN (NEW.copied_from != '' OR EXISTS (SELECT 1 FROM settings WHERE key = NEW.key AND copied_from != '')) BEGIN SELECT attn_require_copy_applier('settings', NEW.key); END;
CREATE TRIGGER refuse_copied_settings_update BEFORE UPDATE ON settings WHEN (OLD.copied_from != '' OR NEW.copied_from != '') BEGIN SELECT attn_require_copy_applier('settings', OLD.key); END;
CREATE TRIGGER refuse_copied_terminal_bindings_delete BEFORE DELETE ON terminal_bindings WHEN (EXISTS (SELECT 1 FROM sessions WHERE id = OLD.session_id AND copied_from != '')) BEGIN SELECT attn_require_copy_applier('terminal_bindings', OLD.terminal_id); END;
CREATE TRIGGER refuse_copied_terminal_bindings_insert BEFORE INSERT ON terminal_bindings WHEN (EXISTS (SELECT 1 FROM sessions WHERE id = NEW.session_id AND copied_from != '') OR EXISTS (SELECT 1 FROM terminal_bindings b JOIN sessions s ON s.id = b.session_id WHERE b.terminal_id = NEW.terminal_id AND s.copied_from != '')) BEGIN SELECT attn_require_copy_applier('terminal_bindings', NEW.terminal_id); END;
CREATE TRIGGER refuse_copied_terminal_bindings_update BEFORE UPDATE ON terminal_bindings WHEN (EXISTS (SELECT 1 FROM sessions WHERE id = OLD.session_id AND copied_from != '') OR EXISTS (SELECT 1 FROM sessions WHERE id = NEW.session_id AND copied_from != '')) BEGIN SELECT attn_require_copy_applier('terminal_bindings', OLD.terminal_id); END;
CREATE TRIGGER remember_remaining_session_desktop AFTER DELETE ON desktop_panes WHEN OLD.session_id != '' AND EXISTS (SELECT 1 FROM desktop_panes WHERE session_id = OLD.session_id) BEGIN UPDATE sessions SET last_desktop_id = (SELECT desktop_id FROM desktop_panes WHERE session_id = OLD.session_id ORDER BY created_at DESC, pane_id DESC LIMIT 1) WHERE id = OLD.session_id; END;
CREATE TRIGGER remember_session_desktop AFTER INSERT ON desktop_panes WHEN NEW.session_id != '' BEGIN UPDATE sessions SET last_desktop_id = (SELECT desktop_id FROM desktop_panes WHERE session_id = NEW.session_id ORDER BY created_at DESC, pane_id DESC LIMIT 1) WHERE id = NEW.session_id; END;
CREATE VIEW sessions_with_runtime AS SELECT s.*, COALESCE(r.state, 'launching') AS state, COALESCE(r.state_since, s.created_at) AS state_since, COALESCE(r.state_updated_at, s.created_at) AS state_updated_at, COALESCE(r.last_seen, s.created_at) AS last_seen, r.branch AS branch, COALESCE(r.is_worktree, 0) AS is_worktree, r.main_repo AS main_repo, COALESCE(r.repository, '') AS repository, COALESCE(r.agent_metadata, '') AS agent_metadata, COALESCE(r.agent_driver_plugin_name, '') AS agent_driver_plugin_name, COALESCE(r.agent_driver_run_id, '') AS agent_driver_run_id, COALESCE(r.agent_driver_report_seq, 0) AS agent_driver_report_seq, COALESCE(r.agent_driver_transcript_path, '') AS agent_driver_transcript_path, COALESCE(r.turn_settled_at, '') AS turn_settled_at, COALESCE(r.turn_opened_at, '') AS turn_opened_at, COALESCE(r.turn_snoozed_until, '') AS turn_snoozed_until, COALESCE(r.turn_agent_at, '') AS turn_agent_at, COALESCE(r.turn_requested_at, '') AS turn_requested_at, r.last_model_request_at AS last_model_request_at, COALESCE(r.harness_title, '') AS harness_title, COALESCE(r.session_cost_json, '') AS session_cost_json, COALESCE(r.pending_conversations, '') AS pending_conversations, COALESCE(r.pull_requests, '') AS pull_requests FROM sessions s LEFT JOIN session_runtime r ON r.session_id = s.id;
